import csv
import io
import re
from collections import Counter
from typing import List, Optional, Sequence, Tuple


EXPECTED_WIDTH = 9


def _is_valid_closing_quote(text: str, pos: int, delimiters: Sequence[str]) -> bool:
    j = pos + 1
    while j < len(text) and text[j] in " \t":
        j += 1
    return (
        j >= len(text)
        or text[j] in delimiters
        or text[j] == "\n"
        or text[j] == "\r"
    )


def _has_closing_quote(text: str, start: int, quote: str, delimiters: Sequence[str]) -> bool:
    i = start + 1
    while i < len(text):
        if text[i] == quote:
            if i + 1 < len(text) and text[i + 1] == quote:
                i += 2
                continue
            if _is_valid_closing_quote(text, i, delimiters):
                return True
        i += 1
    return False


def _split_logical_records(raw: str) -> List[str]:
    records: List[str] = []
    delimiters = (",", ";")
    start = 0
    i = 0
    quote: Optional[str] = None
    field_has_nonspace = False

    while i < len(raw):
        ch = raw[i]

        if quote is not None:
            if ch == quote:
                if i + 1 < len(raw) and raw[i + 1] == quote:
                    i += 2
                    continue
                if _is_valid_closing_quote(raw, i, delimiters):
                    quote = None
            i += 1
            continue

        if ch in delimiters:
            field_has_nonspace = False
            i += 1
            continue

        if ch in ('"', "'") and not field_has_nonspace:
            if _has_closing_quote(raw, i, ch, delimiters):
                quote = ch
                i += 1
                continue

        if ch == "\r" or ch == "\n":
            records.append(raw[start:i])
            if ch == "\r" and i + 1 < len(raw) and raw[i + 1] == "\n":
                i += 2
            else:
                i += 1
            start = i
            field_has_nonspace = False
            continue

        if ch not in " \t":
            field_has_nonspace = True
        i += 1

    if start < len(raw):
        records.append(raw[start:])
    return records


def _parse_record(record: str, delimiters: Sequence[str]) -> List[str]:
    fields: List[str] = []
    current: List[str] = []
    quote: Optional[str] = None
    field_has_nonspace = False
    i = 0

    while i < len(record):
        ch = record[i]

        if quote is not None:
            if ch == quote:
                if i + 1 < len(record) and record[i + 1] == quote:
                    current.append(quote)
                    i += 2
                    continue
                if _is_valid_closing_quote(record, i, delimiters):
                    quote = None
                    i += 1
                    continue
            current.append(ch)
            i += 1
            continue

        if ch in delimiters:
            fields.append("".join(current))
            current = []
            field_has_nonspace = False
            i += 1
            continue

        if ch in ('"', "'") and not field_has_nonspace:
            if _has_closing_quote(record, i, ch, delimiters):
                quote = ch
                i += 1
                continue

        current.append(ch)
        if ch not in " \t":
            field_has_nonspace = True
        i += 1

    fields.append("".join(current))
    return fields


def _signature(value: str) -> str:
    stripped = value.strip()
    if stripped == "":
        return "empty"
    if re.fullmatch(r"[+-]?\d+", stripped):
        return "integer"
    if re.fullmatch(r"[$€£¥]?\s*[+-]?(?:\d+(?:[.,]\d*)?|[.,]\d+)%?", stripped):
        return "number"
    if re.fullmatch(r"\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}", stripped):
        return "date"
    if re.fullmatch(r"\d{1,2}:\d{2}(?::\d{2})?(?:\s*[APap][Mm])?", stripped):
        return "time"
    if re.match(r"(?i)^(?:https?|ftp)://", stripped):
        return "url"
    if re.fullmatch(r"[\w.+-]+@[\w.-]+\.[A-Za-z]{2,}", stripped):
        return "email"
    return "text"


def _data_likeness(row: Sequence[str]) -> int:
    useful = {"integer", "number", "date", "time", "url", "email"}
    return sum(1 for value in row if _signature(value) in useful)


def _header_likeness(row: Sequence[str]) -> int:
    score = 0
    for value in row:
        stripped = value.strip()
        sig = _signature(value)
        if sig in {"integer", "number", "date", "time", "url", "email"}:
            score -= 3
        elif re.search(r"[A-Za-z]", stripped):
            score += 2
        elif stripped:
            score -= 1
    return score


def _best_width_parse(record: str) -> Tuple[List[str], bool]:
    comma = _parse_record(record, (",",))
    if len(comma) == EXPECTED_WIDTH:
        return comma, True

    mixed = _parse_record(record, (",", ";"))
    if len(mixed) == EXPECTED_WIDTH:
        return mixed, True

    if abs(len(mixed) - EXPECTED_WIDTH) < abs(len(comma) - EXPECTED_WIDTH):
        return mixed, False
    return comma, False


def _find_header(records: Sequence[str]) -> Optional[int]:
    candidates: List[Tuple[int, int]] = []

    for index, record in enumerate(records):
        if record.strip() == "":
            continue
        row = _parse_record(record, (",",))
        if len(row) != EXPECTED_WIDTH:
            continue

        score = _header_likeness(row) * 4 - _data_likeness(row) * 5

        following_seen = 0
        j = index + 1
        while j < len(records) and following_seen < 6:
            if records[j].strip() != "":
                next_row, exact = _best_width_parse(records[j])
                if exact:
                    score += 3
                else:
                    score -= min(abs(len(next_row) - EXPECTED_WIDTH), 3)
                if following_seen == 0:
                    score += _data_likeness(next_row) * 4
                following_seen += 1
            j += 1

        score -= index
        candidates.append((score, index))

    if not candidates:
        return None
    candidates.sort(key=lambda item: (-item[0], item[1]))
    return candidates[0][1]


def _profile_score(
    row: Sequence[str],
    profiles: Sequence[Counter],
    header: Sequence[str]
) -> int:
    score = 0
    descriptive_words = (
        "description", "comment", "note", "address", "title",
        "name", "details", "message", "text"
    )

    for index, value in enumerate(row):
        sig = _signature(value)
        if index < len(profiles):
            score += profiles[index][sig] * 3
        if index < len(header):
            name = header[index].strip().lower()
            if any(word in name for word in descriptive_words) and "," in value:
                score += 2
    return score


def _normalize_width(
    row: List[str],
    profiles: Sequence[Counter],
    header: Sequence[str]
) -> List[str]:
    width = len(header)

    if len(row) == width:
        return row

    if len(row) > width:
        excess = len(row) - width
        best_row: Optional[List[str]] = None
        best_score: Optional[int] = None

        for position in range(width):
            end = position + excess + 1
            if end > len(row):
                continue
            candidate = (
                row[:position]
                + [",".join(row[position:end])]
                + row[end:]
            )
            score = _profile_score(candidate, profiles, header)
            if best_score is None or score > best_score:
                best_score = score
                best_row = candidate

        return best_row if best_row is not None else row[:width - 1] + [",".join(row[width - 1:])]

    missing = width - len(row)
    if not profiles:
        return row + [""] * missing

    best_row = None
    best_score = None
    for position in range(len(row) + 1):
        candidate = row[:position] + [""] * missing + row[position:]
        score = _profile_score(candidate, profiles, header)
        if best_score is None or score > best_score:
            best_score = score
            best_row = candidate

    return best_row if best_row is not None else row + [""] * missing


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = _split_logical_records(raw_csv)
    if not records:
        return {"columns": [], "rows": []}

    header_index = _find_header(records)
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = _parse_record(records[header_index], (",",))
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")

    profiles = [Counter() for _ in columns]
    rows: List[List[str]] = []

    for record in records[header_index + 1:]:
        parsed, _ = _best_width_parse(record)
        normalized = _normalize_width(parsed, profiles, columns)
        rows.append([str(value) for value in normalized])

        for index, value in enumerate(normalized):
            if index < len(profiles):
                profiles[index][_signature(value)] += 1

    return {"columns": [str(value) for value in columns], "rows": rows}
